SELECT 

WHERE s.student_id = #{studentId} AND s.academic_term = #{term}
ORDER BY i.sort_order, i.id

SELECT 

WHERE s.student_id = #{studentId} AND s.academic_term = #{term} AND s.source = #{source}
ORDER BY i.sort_order, i.id

SELECT 

WHERE s.academic_term = #{term}

    AND sp.counselor_id = #{scopeCounselorId}

ORDER BY s.student_id, i.sort_order

SELECT DISTINCT s.student_id, COALESCE(NULLIF(sp.class_name, ''), '未填班级') AS class_name FROM eval_score s LEFT JOIN student_profile sp ON sp.user_id = s.student_id AND sp.deleted = 0 WHERE s.academic_term = #{term}
AND sp.counselor_id = #{scopeCounselorId}
ORDER BY class_name, s.student_id

SELECT COUNT(DISTINCT s.student_id)
FROM eval_score s
LEFT JOIN student_profile sp ON sp.user_id = s.student_id AND sp.deleted = 0
WHERE s.academic_term = #{term}

    AND sp.counselor_id = #{scopeCounselorId}
